import React, { useState, useEffect } from "react";
import {
  Truck,
  Users,
  Clock,
  DollarSign,
  LogOut,
  User,
  CreditCard,
  List,
  Menu,
  X,
} from "lucide-react";
import { useNavigate } from "react-router-dom";

function Admindashboard() {
  const [menuOpen, setMenuOpen] = useState(false);
  const navigate = useNavigate();

  // ✅ Admin check
  useEffect(() => {
    const token = localStorage.getItem("admintoken");
    const user = JSON.parse(localStorage.getItem("user") || "{}");

    if (!token || !user.is_admin) {
      navigate("/login");
    }
  }, [navigate]);

  const stats = [
    { title: "Total Orders", value: "12,450", icon: <Truck size={28} />, color: "#2563eb" },
    { title: "Active Partners", value: "520", icon: <Users size={28} />, color: "#16a34a" },
    { title: "Pending Deliveries", value: "87", icon: <Clock size={28} />, color: "#f59e0b" },
    { title: "Revenue", value: "₹8,75,000", icon: <DollarSign size={28} />, color: "#dc2626" },
  ];

  const orders = [
    { id: 1, orderId: "ORD123", customer: "Ravi Kumar", status: "Delivered", date: "2025-09-05" },
    { id: 2, orderId: "ORD124", customer: "Anita Sharma", status: "Pending", date: "2025-09-06" },
    { id: 3, orderId: "ORD125", customer: "Mohit Verma", status: "Dispatched", date: "2025-09-06" },
  ];

  const handleLogout = () => {
    localStorage.removeItem("admintoken");
    localStorage.removeItem("user");
    navigate("/login");
  };

  return (
    <div style={pageStyle}>
      {/* ---------- Header ---------- */}
      <header style={headerStyle}>
        <h2 style={logoStyle}>🚚 Admin Dashboard</h2>

        {/* Desktop Nav */}
        <nav className="desktop-nav" style={navStyle}>
          <a href="/admin-orders" style={navLink}><List size={18}/> Orders</a>
          <a href="/payments" style={navLink}><CreditCard size={18}/> Payments</a>
          <a href="/profile" style={navLink}><User size={18}/> Profile</a>
          <button onClick={handleLogout} style={logoutBtn}><LogOut size={18}/> Logout</button>
        </nav>

        {/* Mobile Menu Button */}
        <button className="menu-btn" onClick={() => setMenuOpen(!menuOpen)} style={menuBtn}>
          {menuOpen ? <X size={28}/> : <Menu size={28}/>}
        </button>
      </header>

      {/* Mobile Drawer */}
      {menuOpen && (
        <div style={mobileMenu}>
          <a href="/orders" style={mobileLink}><List size={18}/> Orders</a>
          <a href="/admin-payments" style={mobileLink}><CreditCard size={18}/> Payments</a>
          <a href="/profile" style={mobileLink}><User size={18}/> Profile</a>
          <button onClick={handleLogout} style={mobileLink}><LogOut size={18}/> Logout</button>
        </div>
      )}

      {/* ---------- Stats ---------- */}
      <h1 style={headingStyle}>📊 Overview</h1>
      <div style={statsGrid} className="stats-grid">
        {stats.map((stat, index) => (
          <div key={index} style={{ ...statCard, borderTop: `5px solid ${stat.color}` }} className="stat-card">
            <div style={{ color: stat.color, marginBottom: "0.5rem" }}>{stat.icon}</div>
            <h3 style={statTitle}>{stat.title}</h3>
            <p style={statValue}>{stat.value}</p>
          </div>
        ))}
      </div>

      {/* ---------- Orders ---------- */}
      <div style={ordersContainer}>
        <h2 style={subHeading}>Recent Orders</h2>
        <div style={{ overflowX: "auto" }}>
          <table style={tableStyle}>
            <thead>
              <tr>
                <th style={thStyle}>Order ID</th>
                <th style={thStyle}>Customer</th>
                <th style={thStyle}>Status</th>
                <th style={thStyle}>Date</th>
              </tr>
            </thead>
            <tbody>
              {orders.map((order) => (
                <tr key={order.id} style={rowHover}>
                  <td style={tdStyle}>{order.orderId}</td>
                  <td style={tdStyle}>{order.customer}</td>
                  <td style={tdStyle}>
                    <span style={{
                      padding: "4px 10px",
                      borderRadius: "12px",
                      fontWeight: "600",
                      color: "#fff",
                      background:
                        order.status === "Pending" ? "#f59e0b" :
                        order.status === "Delivered" ? "#16a34a" : "#2563eb"
                    }}>
                      {order.status}
                    </span>
                  </td>
                  <td style={tdStyle}>{order.date}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* ---------- Responsive Styling ---------- */}
      <style>{`
        @media (max-width: 768px) {
          .desktop-nav { display: none; }
          .menu-btn { display: block !important; }
          .stats-grid { grid-template-columns: 1fr !important; }
          .stat-card { text-align: center; }
          table { font-size: 0.85rem !important; }
        }
        .stat-card:hover {
          transform: translateY(-6px);
          box-shadow: 0 8px 18px rgba(0,0,0,0.12);
          transition: all 0.3s ease;
        }
        tr:hover { background-color: #f9fafb; }
      `}</style>
    </div>
  );
}

/* ---------- Styles ---------- */
const pageStyle = { padding: "2rem", background: "#f9fafb", minHeight: "100vh", fontFamily: "Inter, sans-serif" };

const headerStyle = {
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  background: "linear-gradient(90deg, #2563eb, #1d4ed8)",
  padding: "1rem 2rem",
  borderRadius: "12px",
  color: "#fff",
  position: "sticky",
  top: "0",
  zIndex: "10",
};

const logoStyle = { fontWeight: "700", fontSize: "1.4rem" };

const navStyle = { display: "flex", alignItems: "center" };

const navLink = { marginLeft: "1.5rem", textDecoration: "none", color: "#fff", fontWeight: "500", display: "inline-flex", alignItems: "center", gap: "0.4rem" };

